				/*initBntTrxlCatalogInfoUplolad*/			
           DELETE FROM BNTTRXL
           WHERE DOC_NAME = 'CTLG_MD'
             AND TARGET = #{st_user_id}


				/*deleteBntTrxlCaInfo*/			
           DELETE FROM BNTTRXL
           WHERE DOC_NAME = 'CTLG_MD'
             AND TARGET = #{st_user_id}
             AND KEY_1 = #{BUYER}
             AND KEY_2 = #{BUYER_ITEM_NO}
             AND KEY_3 = #{SEQ}

mapper.select:
/*getBnttrxlCaInfoList*/ SELECT A.DOC_NAME , A.USER_ID , A.BUYER , A.BUYER_ITEM_NO , A.STATUS_CODE , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M161' AND CODE = A.STATUS_CODE) AS STATUS_CODE_TEXT , A.CHECK_TEXT , A.BELOW_COMORG_TEXT , A.AGENT_TEXT , A.CONTRACT_NO , A.CONTRACT_SEQ , A.MAKER_CODE , A.MAKER_NAME , A.ORIGIN_CODE , A.MAKER_PART_NO , A.BELOW_COMORG_CODE , A.AGENT , A.DESCRIPTION , A.SPECIFICATION , A.CH_CMS_CATEG_ID , A.CH_CMS_CATEG_NAME , A.CMS_CATLG_ID , A.GBN , A.SEQ FROM (SELECT DOC_NAME , TARGET AS USER_ID , KEY_1 AS BUYER , KEY_2 AS BUYER_ITEM_NO , DECODE((SELECT DECODE(COUNT(*),0,'D1','C') FLAG FROM ICOMBYIT WHERE BUYER = TRXL.KEY_1 AND BUYER_ITEM_NO = TRXL.KEY_2 AND STATUS <> 'D'), 'C', DECODE( ( SELECT DECODE(COUNT(*),0,'D2','C') AS FLAG FROM ( SELECT BUYER FLAG FROM MIS_BUYER_MNG WHERE YEAR = TO_CHAR(SYSDATE, 'YYYY') AND BUYER IN (SELECT BELOW_COMORG_CODE FROM ICOMCQDT WHERE BUYER = TRXL.KEY_1 AND BUYER_ITEM_NO = TRXL.KEY_2) AND KEP_USER_ID = TRXL.TARGET AND STATUS <> 'O'
UNION ALL
SELECT COM_CODE FROM ICOMLUSR WHERE 1=1 AND USER_ID = TRXL.TARGET AND DEPARTMENT IN (SELECT CODE FROM ICOMCOD1 WHERE TYPE = 'SOURDEPT') AND NOT EXISTS ( SELECT 'x' FROM ICOMCOD1 WHERE TYPE = 'EXCCMPY' AND FLAG = 'Y' AND CODE IN (SELECT COM_CODE FROM ICOMCMPY WHERE BYCA_COMORG_CODE = TRXL.KEY_1) ) ) ) , 'C', (SELECT DECODE(COUNT(*), 1, 'C', 'D3') FROM BNTTRXL TRXL2 WHERE TRXL2.DOC_NAME = TRXL.DOC_NAME AND TRXL2.TARGET = TRXL.TARGET AND TRXL2.KEY_1 = TRXL.KEY_1 AND TRXL2.KEY_2 = TRXL.KEY_2), 'D2' ), 'D1') AS STATUS_CODE , '변경후' AS CHECK_TEXT , KEY_5 AS BELOW_COMORG_TEXT , KEY_6 AS AGENT_TEXT , KEY_7 AS CONTRACT_NO , KEY_8 AS CONTRACT_SEQ , DECODE(KEY_11,'★','',KEY_11) AS MAKER_CODE , DECODE(KEY_12,'★','',KEY_12) AS MAKER_NAME , DECODE(KEY_13,'★','',KEY_13) AS ORIGIN_CODE , DECODE(KEY_14,'★','',KEY_14) AS MAKER_PART_NO , KEY_15 AS BELOW_COMORG_CODE , KEY_16 AS AGENT , DECODE(KEY_22,'★','',KEY_22) AS DESCRIPTION , DECODE(KEY_23,'★','',KEY_23) AS SPECIFICATION , DECODE(KEY_24,'★','',KEY_24) AS CH_CMS_CATEG_ID , (SELECT CATEG_NAME FROM CMSCATEG CMS WHERE CMS.CMS_CATEG_ID = KEY_24) AS CH_CMS_CATEG_NAME , '' AS CMS_CATLG_ID , '0' AS GBN , KEY_3 AS SEQ FROM BNTTRXL TRXL WHERE TRXL.DOC_NAME = 'CTLG_MD' AND TRXL.TARGET = #{st_user_id} ) A WHERE 1=1
AND A.STATUS_CODE = #{st_status_text}
ORDER BY A.BUYER, A.BUYER_ITEM_NO
